<script setup>
import { reactive, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toMonitoringQueryDraft,toMonitoringQueryPayload } from '../domain/monitoring-query-write.mjs';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String});const emit=defineEmits(['cancel','save']);const draft=reactive({...toMonitoringQueryDraft()});watch(()=>props.record,(record)=>Object.assign(draft,toMonitoringQueryDraft(record)),{immediate:true});const categories=[{value:'brand',label:'Thương hiệu'},{value:'industry',label:'Ngành'},{value:'competitor',label:'Đối thủ'}];const types=[{value:'news',label:'Báo chí'},{value:'social',label:'Mạng xã hội'},{value:'web',label:'Web'}];const states=[{value:true,label:'Bật'},{value:false,label:'Tắt'}];function submit(){emit('save',toMonitoringQueryPayload(draft));}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto flex min-h-[620px] max-w-[900px] flex-col overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="border-b border-[var(--mds-border-light)] px-5 py-4"><h1 class="text-[20px] font-semibold">{{editing?'Sửa bộ từ khóa':'Thêm bộ từ khóa'}}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Lưu cấu hình không tự kích hoạt lượt quét hay gọi AI.</p></header><main class="min-h-0 flex-1 space-y-4 overflow-y-auto px-5 py-4"><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error}}</p><div class="grid gap-4 md:grid-cols-2"><label class="md:col-span-2"><span class="mb-1 block text-[13px] font-medium">Tên bộ từ khóa</span><MInput v-model="draft.name" placeholder="Theo dõi thương hiệu MISA"/></label><label><span class="mb-1 block text-[13px] font-medium">Phân loại</span><MSelect v-model="draft.category" :options="categories"/></label><label><span class="mb-1 block text-[13px] font-medium">Nguồn quét</span><MSelect v-model="draft.queryType" :options="types"/></label><label class="md:col-span-2"><span class="mb-1 block text-[13px] font-medium">Từ khóa bao gồm</span><MTextarea v-model="draft.include" :rows="3" placeholder="MISA, AMIS (ngăn cách bằng dấu phẩy)"/></label><label class="md:col-span-2"><span class="mb-1 block text-[13px] font-medium">Từ khóa loại trừ</span><MTextarea v-model="draft.exclude" :rows="3" placeholder="Từ khóa không liên quan (ngăn cách bằng dấu phẩy)"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.enabled" :options="states"/></label></div></main><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" @click="submit">{{editing?'Lưu thay đổi':'Thêm bộ từ khóa'}}</MButton></footer></form></section></template>
